/**
 * Cambodia-first intent test corpus (§20).
 *
 * Every case records the customer's raw message and what the engine must make of
 * it: intent, extracted quantity / size / colour, purchase-confidence band, and
 * whether [Prepare order] may be surfaced.
 *
 * The corpus is written from the Cambodian language brief, not from the engine's
 * internals — do not "fix" a case by relaxing an expectation. If a case is
 * genuinely wrong, correct the brief first, then the lexicon.
 */
import type { ConfidenceBand, LineItemCandidate, PrimaryIntent } from "@/lib/intent";

export interface CorpusCase {
  /** the message exactly as a customer would send it */
  input: string;
  intent: PrimaryIntent;
  band: ConfidenceBand;
  /** whether [Prepare order] may be surfaced for this message */
  prepareOrder: boolean;
  /** first candidate item — undefined means the engine must not invent one */
  quantity?: number;
  size?: string;
  color?: string;
  /** set when the message must produce more than one line item */
  items?: LineItemCandidate[];
  note?: string;
}

